     7→  userName: string;
     8→  score: number;
     9→  rank: number;
    10→  characterType?: string;
    11→}
    12→
    13→export interface SubmitScoreResponse {
    14→  success: boolean;
    15→  isNewRecord: boolean;
    16→  previousScore: number | null;
    17→  newScore: number;
    18→  rank: number | null;
    19→  message?: string;
    20→}
