scene['scoreText'].setText('점수: 3700'); // UI도 갱신

// 4. 검증 통과 최소 대기 시간 계산
// timeBasedScore = 3700 - 3250 = 450
// minRequiredSec = 450 * 0.1 * 0.5 = 22.5초
console.log('최소', Math.ceil((scene.score - (scene.goldCollected*20 + scene.diamondCollected*40 + scene.topazCollected*80 + scene.rainbowCollected*90)) * 0.1 * 0.5), '초 대기 후 게임오버 처리');

// 5. 강제 게임오버 (똥에 맞은 척)
// 대기 후 아무 똥에 닿으면 자연스럽게 제출 or 직접 호출:
